#include "al_ui.h"
#include "al_viewport.h"
namespace al {
bool rayBox(Vec3 o,Vec3 ray,Vec3 lo,Vec3 hi,double& t,int* face){double near=0,far=1e30;int side=-1;for(int a=0;a<3;a++){if(std::abs(ray[a])<1e-12){if(o[a]<lo[a]||o[a]>hi[a])return false;continue;}double x=(lo[a]-o[a])/ray[a],y=(hi[a]-o[a])/ray[a];int d=a==0?0:a==1?2:1;if(x>y){std::swap(x,y);d=opposite(d);}if(x>near){near=x;side=d;}far=std::min(far,y);if(far<near)return false;}t=near;if(face)*face=side;return far>=0;}
}
namespace alui {
static Vec3 workbenchPosition(const Repo& r,size_t i){return settings.workbenchOrigin+mul(Vec3{double(i%8)*settings.spacing,double(i/8)*settings.spacing,0},r.cellSize)+r.blocks[i].workbenchPos;}
static void glyph(std::vector<float>& lines,Vec3 center,double radius,int vertices){for(int n=0;n<vertices;n++){double a=n*6.283185307179586/vertices,b=(n+1)*6.283185307179586/vertices;mapbuild::line(lines,center+Vec3{std::cos(a)*radius,std::sin(a)*radius,0},center+Vec3{std::cos(b)*radius,std::sin(b)*radius,0});}}
static void viewportMono(){if(!ready||!initialized)return;std::vector<float> lines=preview.lines;auto r=currentRepo();auto b=currentBuilder();if(page==0&&b){for(auto& repo:repos)if(repo.uid==b->repoUid)r=&repo;if(r){auto lo=b->worldOrigin+mul(vec(b->levelData.position),r->cellSize);mapbuild::wire(lines,lo,lo+mul(vec(b->levelData.size),r->cellSize));auto sl=b->worldOrigin+mul(vec(b->selection.min),r->cellSize),sh=b->worldOrigin+mul(vec(b->selection.max),r->cellSize);mapbuild::wire(lines,sl,sh);for(int axis=0;axis<3;axis++)for(int face:{0,1}){int u=(axis+1)%3,v=(axis+2)%3;for(int p=b->selection.min[u];p<=b->selection.max[u];p++){auto a=sl,z=sh;a[axis]=z[axis]=face?sh[axis]:sl[axis];a[u]=z[u]=b->worldOrigin[u]+p*r->cellSize[u];mapbuild::line(lines,a,z);}}
 if(settings.groupsToggle)for(size_t i=0;i<b->inputWave.size();i++){auto c=b->inputWave[i];if(c.containAll())continue;auto center=b->worldOrigin+mul(vec(position(i,b->levelData.size)+b->levelData.position)+Vec3{.5,.5,.5},r->cellSize);double radius=std::min(r->cellSize.x,r->cellSize.y)/6;uint32_t mask=uint32_t(c.groups);if(mask==1)glyph(lines,center,radius,8);else if(mask==2){mapbuild::wire(lines,center-Vec3{radius,radius,radius},center+Vec3{radius,radius,radius});mapbuild::line(lines,center-Vec3{radius,radius,radius},center+Vec3{radius,radius,radius});}else if(mask&&(mask&(mask-1))==0){int n=0;while(!(mask&(1u<<n)))n++;glyph(lines,center,radius,3+n%5);}else for(int a=0;a<3;a++){auto lo=center,hi=center;lo[a]-=radius;hi[a]+=radius;mapbuild::line(lines,lo,hi);}}}}
 if((page==1||page==2)&&r){for(size_t i=0;i<r->blocks.size();i++){auto lo=workbenchPosition(*r,i);mapbuild::wire(lines,lo,lo+r->cellSize);}auto bp=currentBlock();auto v=currentVariant();if(bp&&v&&page==2){auto lo=workbenchPosition(*r,size_t(bp-r->blocks.data()))+v->editorOffset;if(settings.editMode==2){for(int c=0;c<8;c++){auto p=lo+mul({double(c&1),double((c>>1)&1),double((c>>2)&1)},r->cellSize);if(v->fill&(1<<c))mapbuild::wire(lines,p-Vec3{4,4,4},p+Vec3{4,4,4});else{mapbuild::line(lines,p-Vec3{5,0,0},p+Vec3{5,0,0});mapbuild::line(lines,p-Vec3{0,5,0},p+Vec3{0,5,0});}}}if(settings.editMode==1){int count=0;for(int d=0;d<6;d++)for(size_t i=0;i<r->blocks.size()&&count<settings.maxConnectionsDrawCount;i++){if(!settings.drawSelfConnections&& &r->blocks[i]==bp)continue;for(auto ov:r->blocks[i].variants)if(ov.sideIds[opposite(d)]==v->sideIds[d]){auto src=lo+r->cellSize*.5+mul(vec(delta[d]),r->cellSize)*.5,dst=workbenchPosition(*r,i)+r->cellSize*.5-mul(vec(delta[d]),r->cellSize)*.5;mapbuild::line(lines,src,dst);count++;break;}}}if(settings.editMode==3)for(auto ref:v->layerSettings.dependencies)if(auto dep=block(*r,ref.blockUid)){auto dst=workbenchPosition(*r,size_t(dep-r->blocks.data()))+r->cellSize*.5;mapbuild::line(lines,lo+r->cellSize*.5,dst);}}}
 mapbuild::dedup(lines);if(lines.size()>16384*6)lines.resize(16384*6);host->preview_lines(lines.data(),lines.size()/6);
}
}
